  await savePolicies(policies,enabled?'Politika etkinleştirildi. Yeni kimlik doğrulama denemelerinde değerlendirilir.':'Politika devre dışı bırakıldı. Ayarları korundu; yeni kimlik doğrulama denemelerinde değerlendirilmez.');
