function renderPKI(){const info=state.pki_public,parent=$('pki-info');parent.replaceChildren();const ready=!!info?.initialized;$('pki-summary').textContent=!can('certificates.authority')?'Yetki yok':ready?'CA oluşturuldu':'Hazırlanacak';$('pki-status-label').textContent=ready?'CA hazır':'Henüz CA oluşturulmadı';$('pki-status-dot').classList.toggle('ready',ready);if(!ready){parent.textContent='Henüz CA oluşturulmadı.';return;}const list=document.createElement('dl');list.className='pki-information';const rows=[['Kurulum kimliği',info.instance_id],['CRL sürümü',String(info.crl_number)]];for(const [kind,label]of [['root','Root CA'],['issuer','İmzalayan CA']])rows.push([label+' SHA256',info[kind].fingerprint_sha256],[label+' son geçerlilik',info[kind].not_after]);for(const [label,value]of rows){const row=document.createElement('div'),term=document.createElement('dt'),description=document.createElement('dd');term.textContent=label;description.textContent=value;row.append(term,description);list.append(row);}parent.append(list);}
