async function refresh({checkSession=true,includeAudit=true}={}){
  if(checkSession){const auth=await api('/api/auth/session');session=auth;csrf=auth.csrf;}
  state=await api('/api/state');
  $('panel-version').textContent='Ubuntu · '+state.version;
  if(setupBaseRevision!==null&&!setupSaving&&!setupHasEdits()&&!setupAwaitingRead)fillConfig({force:true});
  $('account-name').textContent=session.user.username+' · '+session.user.profile_name;
  $('revision').textContent='Kayıt sürümü '+state.revision;
  renderPolicies();renderPKI();renderDirectoryStatus();renderOverview();applyPermissions();
  if(includeAudit)await loadAudit();
}
async function loadAudit(){return loadAuditHistory({background:true});}
function panelRecovery(error){
  if(error.code==='SESSION_CHANGED')return;
  $('panel-loading').hidden=true;$('login-title').textContent='Panel bağlantısı';$('login-description').textContent='Bağlantı yeniden denenebilir.';
  $('workspace').hidden=true;$('account-bar').hidden=true;$('login').hidden=false;
  $('login-form').hidden=true;$('panel-recovery').hidden=false;
  $('panel-recovery-message').textContent=session?'Girişiniz doğrulandı, ancak panel verileri yüklenemedi. Parolanızı yeniden girmeniz gerekmiyor.':'Panel bağlantısı tamamlanamadı. Yeniden deneyebilirsiniz.';
  message(error.message,'error');
}
async function openPanel(){
  await refresh({checkSession:false,includeAudit:false});
  fillConfig();$('panel-loading').hidden=true;$('panel-recovery').hidden=true;$('login-form').hidden=false;
  $('login').hidden=true;$('workspace').hidden=false;$('account-bar').hidden=false;
  showView(document.querySelector('.view:not([hidden])')?.id||'overview');
  // Optional lists cannot turn a valid login into a password prompt.
  run(()=>loadAudit());
  if(can('policies.rules'))run(()=>loadGroups());
}
async function restorePanel(){
  booting=true;$('login-form').hidden=true;$('panel-recovery').hidden=true;$('panel-loading').hidden=false;$('login-title').textContent='ΛuthWire';$('login-description').textContent='Oturumunuz kontrol ediliyor.';$('unlock').disabled=true;$('panel-retry').disabled=true;
  try{
    const auth=await api('/api/auth/session');
    authGeneration++;session=auth;csrf=auth.csrf;
    await openPanel();
  }catch(error){
    if(error.code==='UNAUTHORIZED'){lock();}
    else panelRecovery(error);
  }finally{booting=false;$('unlock').disabled=false;$('panel-retry').disabled=false;}
}
$('panel-retry').addEventListener('click',()=>{if(!booting&&!loginBusy)restorePanel();});
async function savePolicies(policies=state.policies,successMessage='Politikalar kaydedildi.'){
  if(policySaving)return;
  const generation=authGeneration;policySaving=true;applyPermissions();
  try{
    await api('/api/policies',{expected_revision:state.revision,policies});
    rejectedConflicts=[];await refresh();message(successMessage);
  }finally{if(generation===authGeneration){policySaving=false;applyPermissions();}}
}
