async function loadSystem(){if(!['system.administrators','system.profiles'].some(k=>can(k)))return;const generation=authGeneration,request=++systemRequest;systemLoading=true;applyPermissions();try{const value=await api('/api/system');if(request!==systemRequest)return;systemState=value;renderSystem();}finally{if(generation===authGeneration&&request===systemRequest){systemLoading=false;applyPermissions();}}}
function rowActions(parent,text,edit,remove,writable){const row=document.createElement('div');row.className='policy-row';const label=document.createElement('span');label.textContent=text;row.append(label);if(writable){const actions=document.createElement('div');actions.className='actions';for(const [name,fn]of [['Düzenle',edit],['Sil',remove]]){const b=document.createElement('button');b.textContent=name;b.addEventListener('click',()=>run(fn));actions.append(b);}row.append(actions);}parent.append(row);}
function renderSystem(){for(const id of ['admin-users-list','admin-profiles-list'])$(id).replaceChildren();for(const u of systemState.users||[])rowActions($('admin-users-list'),u.username+' • '+u.profile_name+' • '+(u.enabled?'Etkin':'Kapalı'),()=>editUser(u),async()=>{const own=u.id===session.user.id;const last=(systemState.users||[]).length===1;const question='“'+u.username+'” hesabı silinsin mi?'+(last?' Bu son hesaptır; silerseniz panelden yeniden giriş yapılamaz.':own?' Kendi hesabınızı siliyorsunuz; oturumunuz kapanacak.':'');if(confirm(question)){await api('/api/system/users/delete',{expected_revision:systemState.revision,id:u.id});if(own){lock();message('Hesap silindi.');}else{await loadSystem();message('Hesap silindi.');}}},can('system.administrators',true));for(const p of systemState.profiles||[])if(can('system.profiles'))rowActions($('admin-profiles-list'),p.name+' • '+p.mode+' • '+p.users_count+' hesap',()=>editProfile(p),async()=>{if(confirm('“'+p.name+'” profili silinsin mi?')){await api('/api/system/profiles/delete',{expected_revision:systemState.revision,id:p.id});await loadSystem();message('Profil silindi.');}},can('system.profiles',true));$('admin-user-profile').replaceChildren();for(const p of systemState.profiles||[]){const option=document.createElement('option');option.value=p.id;option.textContent=p.name;$('admin-user-profile').append(option);}applyPermissions();}
function editUser(u=null){if(!systemState||systemLoading)return;editingUser=u?.id||'';$('admin-user-form').hidden=false;$('user-form-title').textContent=u?'Kullanıcıyı düzenle':'Yeni kullanıcı';$('admin-username').value=u?.username||'';$('admin-password').value='';$('admin-user-profile').value=u?.profile_id||(systemState.profiles||[]).find(p=>p.name==='Admin_ReadOnly')?.id||systemState.profiles?.[0]?.id||'';$('admin-user-enabled').checked=u?Boolean(u.enabled):true;}
function editProfile(p=null){if(!systemState||systemLoading)return;editingProfile=p?.id||'';$('admin-profile-form').hidden=false;$('profile-form-title').textContent=p?'Profili düzenle':'Yeni profil';$('admin-profile-name').value=p?.name||'';$('admin-profile-mode').value=p?.mode||'Custom';renderPermissions(p?.grants||{});}
function renderPermissions(grants){const parent=$('profile-permissions');parent.replaceChildren();const table=document.createElement('table');table.className='permissions-table';const head=document.createElement('tr');for(const t of ['Menü','Sekme','Yetki']){const th=document.createElement('th');th.textContent=t;head.append(th);}table.append(head);for(const [key,labels]of Object.entries(systemState.resources)){const row=document.createElement('tr');for(const text of labels){const cell=document.createElement('td');cell.textContent=text;row.append(cell);}const cell=document.createElement('td'),select=document.createElement('select');select.dataset.resource=key;for(const [value,label]of [['none','Yetki yok'],['read','Read'],['write','Read / Write']]){const o=document.createElement('option');o.value=value;o.textContent=label;select.append(o);}select.value=grants[key]||'none';cell.append(select);row.append(cell);table.append(row);}parent.append(table);profileMode();}
function profileMode(){const mode=$('admin-profile-mode').value;document.querySelectorAll('[data-resource]').forEach(x=>{x.disabled=mode!=='Custom';if(mode!=='Custom')x.value=mode==='SuperAdmin'?'write':'read';});}
$('login-form').addEventListener('submit',event=>{
  event.preventDefault();if(booting||loginBusy)return;
  loginBusy=true;authGeneration++;
  run(async()=>{
    const button=$('unlock');button.disabled=true;
    try{
      const auth=await api('/api/auth/login',{username:$('login-user').value.trim(),password:$('login-password').value});
      authGeneration++;session=auth;csrf=auth.csrf;
      try{await openPanel();message('Panel açıldı.');}
      catch(error){if(error.code!=='UNAUTHORIZED')panelRecovery(error);throw error;}
    }finally{$('login-password').value='';loginBusy=false;button.disabled=false;}
  });
});
