function adHealthText(code){return ({AD_CREDENTIALS_REJECTED:'AD kayıtlı kullanıcı bilgilerini kabul etmedi; parola, hesap kilidi veya hesap durumunu kontrol edin.',AD_TIMEOUT:'AD bağlantısı zaman aşımına uğradı.',AD_DNS_FAILED:'AD sunucusunun DNS adı çözümlenemedi.',SECRET_STORE_UNAVAILABLE:'Kayıtlı AD parolası açılamadı.'}[code])||'AD bağlantı kontrolü başarısız: '+code+'.';}
async function loadDirectorySettings(){if(!can('directory.connection'))return;const request=++directoryRequest;directoryLoading=true;applyPermissions();try{const d=await api('/api/directory/settings');if(request!==directoryRequest)return;directorySettings=d;for(const [id,key]of [['ad-name','name'],['ad-host','dc_fqdn'],['ad-user','username'],['ad-sync-minutes','sync_minutes'],['ad-check-minutes','check_minutes']])$(id).value=d[key];$('ad-auto').checked=d.automatic_sync;$('ad-ou').value=d.search_base;$('ad-credential-status').textContent=d.credentials_saved?'Parola korumalı kaydedilmiş. Boş bırakırsanız korunur.':'Henüz bağlantı parolası kaydedilmedi.';}finally{if(request===directoryRequest){directoryLoading=false;applyPermissions();}}}

function renderVlans(){const select=$('policy-vlan'),previous=select.value;select.replaceChildren();const empty=document.createElement('option');empty.value='';empty.textContent='VLAN seçin';select.append(empty);for(const v of networkState?.vlans||[]){const o=document.createElement('option');o.value=String(v.id);o.textContent=v.name+' — VLAN '+v.id;select.append(o);}select.value=previous;const parent=$('vlan-list');parent.replaceChildren();for(const v of networkState?.vlans||[]){const row=document.createElement('div');row.className='policy-row';const label=document.createElement('span');label.textContent=v.name+' — VLAN '+v.id+(v.description?' • '+v.description:'');row.append(label);if(can('network.vlans',true)){const edit=document.createElement('button');edit.textContent='Düzenle';edit.addEventListener('click',()=>{editingVlan=v.id;$('vlan-id').value=v.id;$('vlan-name').value=v.name;$('vlan-description').value=v.description;});const remove=document.createElement('button');remove.textContent='Sil';remove.addEventListener('click',()=>run(()=>saveVlans(networkState.vlans.filter(x=>x.id!==v.id))));row.append(edit,remove);}parent.append(row);}if(!networkState?.vlans?.length)parent.textContent='Henüz VLAN tanımlanmadı.';}
function radiusPayload(clients=networkState.radius_clients){return clients.map(x=>({name:x.name,ip:x.ip,access_type:x.access_type||'wired',secret:x.secret||''}));}
async function saveVlans(vlans){await api('/api/network/vlans',{expected_revision:state.revision,vlans});await refresh();await loadNetwork();message('VLAN tanımları kaydedildi.');}
async function saveRadius(clients=networkState.radius_clients){await api('/api/network/radius',{expected_revision:state.revision,radius_clients:radiusPayload(clients),authentication_port:Number($('radius-auth-port').value),accounting_port:Number($('radius-account-port').value)});await refresh();fillConfig();await loadNetwork();message('RADIUS ayarları kaydedildi. Cihaz ayarlarını manuel uygulayın.');}
function renderRadius(){if(!networkState?.radius_clients)return;$('radius-auth-port').value=networkState.authentication_port;$('radius-account-port').value=networkState.accounting_port;const parent=$('radius-list');parent.replaceChildren();for(const c of networkState.radius_clients){const row=document.createElement('div');row.className='policy-row';const label=document.createElement('span');label.textContent=c.name+' • '+c.ip+' • '+(c.access_type==='wireless'?'Kablosuz':'Kablolu')+' • '+(c.secret_saved?'Shared secret kaydedilmiş':'Shared secret gerekli');row.append(label);if(can('network.radius',true)){const edit=document.createElement('button');edit.textContent='Düzenle';edit.addEventListener('click',()=>{editingRadius=c.ip;$('radius-name').value=c.name;$('radius-ip').value=c.ip;$('radius-access-type').value=c.access_type||'wired';$('radius-secret').value='';});const reveal=document.createElement('button');reveal.textContent='Shared secret göster';reveal.disabled=!c.secret_saved;reveal.addEventListener('click',()=>run(async()=>{const v=await api('/api/network/secret/reveal',{ip:c.ip});editingRadius=c.ip;$('radius-name').value=c.name;$('radius-ip').value=c.ip;$('radius-access-type').value=c.access_type||'wired';$('radius-secret').value=v.secret;$('radius-secret').type='text';}));const remove=document.createElement('button');remove.textContent='Sil';remove.addEventListener('click',()=>run(()=>saveRadius(networkState.radius_clients.filter(x=>x.ip!==c.ip))));row.append(edit,reveal,remove);}parent.append(row);}$('radius-instructions').textContent='Switch/AP üzerinde:\nRADIUS Server: ΛuthWire sunucusunun ağ IP adresi ('+(state.config?.appliance_fqdn||'kurulumda tanımlayın')+')\nAuthentication: UDP '+networkState.authentication_port+'\nAccounting: UDP '+networkState.accounting_port+'\nShared secret: cihaz için kaydettiğiniz aynı değer\nPanel adresi 127.0.0.1:8765 RADIUS adresi değildir.';}
async function loadNetwork(){if(!['network.vlans','network.radius','policies.rules'].some(r=>can(r)))return;const request=++networkRequest;networkLoading=true;applyPermissions();try{const value=await api('/api/network');if(request!==networkRequest)return;networkState=value;renderVlans();renderRadius();renderPolicies();}finally{if(request===networkRequest){networkLoading=false;applyPermissions();}}}
