async function pollState(){
  if(!session||booting||loginBusy||pollBusy||directoryBusy||document.hidden||!state)return;
  pollBusy=true;
  try{
    const fresh=await api('/api/state');
    const changed=fresh.directory_public?.synced_at!==state?.directory_public?.synced_at;
    state=fresh;renderDirectoryStatus();renderPolicies();
    $('revision').textContent='Kayıt sürümü '+state.revision;
    if(setupBaseRevision!==null&&!setupSaving&&!setupHasEdits()&&!setupAwaitingRead)fillConfig({force:true});else setupControls();
    if(changed){groupNames.clear();if(!$('identities').hidden&&can('directory.catalog'))await loadDirectory();if(!$('policies').hidden&&can('policies.rules'))await loadGroups();if(!$('simulate').hidden&&can('simulate.scenarios'))await loadGroups('sim');}
  }finally{pollBusy=false;}
}
setInterval(()=>run(pollState),15000);

