const pkiErrors={PKI_HTTPS_REQUIRED:'Sertifika işlemleri için HTTPS panelini kullanın.',PKI_OPERATION_FAILED:'CA işlemi tamamlanamadı. CA parolasını, mevcut CA durumunu ve girişleri kontrol edin.',CSR_INVALID:'Geçerli imzalı, uzantısız PEM CSR gerekli. SAN/EKU/CA alanlarını kaldırın.',CSR_ALREADY_USED:'Bu CSR veya anahtar daha önce kullanılmış. Endpoint üzerinde yeni anahtar ve CSR oluşturun.',ENROLLMENT_LOGIN_FORMAT:'samAccountName@kayıtlı-domain biçimini kullanın; kullanıcı adı 1–20 harf/rakam/nokta/tire/alt çizgi olabilir.',ENROLLMENT_AUTHENTICATION_FAILED:'Kullanıcının AD kimliği doğrulanamadı. Hesabı, parolayı ve Kerberos erişimini kontrol edin; otomatik tekrar yapılmadı.',ENROLLMENT_IDENTITY_REJECTED:'Canlı AD hesabı bulunamadı, etkin değil veya doğrulanmış kullanıcı kimliğiyle eşleşmedi.',ENROLLMENT_DIRECTORY_UNAVAILABLE:'Canlı AD yetki kontrolü tamamlanamadı. Sertifika üretilmedi.',ENROLLMENT_BUSY:'Bir sertifika işlemi devam ediyor.',ENROLLMENT_RETRY_LATER:'Son kayıt denemesinden sonra 30 saniye bekleyin. Otomatik yeniden deneme yapılmaz.'};
function clearPKISecrets(){for(const id of ['pki-password','pki-confirm','pki-user-password','device-signer-password'])$(id).value='';}
function pkiControls(){const write=can('certificates.authority',true),ready=!!state?.pki_public?.initialized;if(!write)pkiDrawer='';$('pki-write').hidden=!write||!pkiDrawer;document.body.classList.toggle('pki-drawer-open',write&&!!pkiDrawer);for(const input of $('pki-write').querySelectorAll('input,textarea,select,button'))input.disabled=!write||pkiBusy;for(const id of ['pki-download-root','pki-download-issuer','pki-download-crl'])$(id).disabled=!ready;for(const id of ['pki-new','pki-open-crl','pki-open-revoke']){$(id).hidden=!write;$(id).disabled=!write||!ready||pkiBusy;}$('pki-open-init').hidden=!write||ready;$('pki-open-init').disabled=!write||pkiBusy;for(const [id,action]of [['pki-init-form','initialize'],['pki-user-form','user'],['pki-revoke-form','revoke'],['pki-crl-form','crl']])$(id).hidden=pkiDrawer!==action||(action==='initialize'&&ready);if(pkiDrawer==='initialize'&&ready)closePKIDrawer();}
function downloadPEM(name,pem){const blob=new Blob([pem],{type:'application/x-pem-file'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();URL.revokeObjectURL(url);}
async function archiveCertificate(cert){if(!confirm('Bu iptal edilmiş sertifika panel listelerinden kaldırılsın mı? CRL ve denetim kaydı korunur.'))return;await api('/api/pki/archive',{serial:cert.serial});pkiOffset=0;await loadCertificates();if(typeof loadDevices==='function')await loadDevices();message('İptal edilmiş sertifika panelden kaldırıldı. CRL ve audit kaydı korunuyor.');}
async function loadCertificates(){if(!can('certificates.authority'))return;const request=++pkiRequest,page=await api('/api/pki/certificates?offset='+pkiOffset);if(request!==pkiRequest)return;pkiRows=page.items;renderCertificateRows();$('pki-count').textContent=page.total+' sertifika';$('pki-previous').disabled=pkiOffset===0;$('pki-next').disabled=pkiOffset+page.items.length>=page.total;pkiControls();}
async function pkiAction(path,data){if(pkiBusy)return;pkiBusy=true;pkiControls();message('Sertifika işlemi yürütülüyor…');try{data.ca_password=$('pki-password').value;const value=await api(path,data);if(value.certificate)downloadPEM('authwire-'+value.serial+'.pem',value.certificate);await refresh();pkiOffset=0;await loadCertificates();closePKIDrawer();message('Sertifika işlemi tamamlandı. RADIUS hizmeti henüz etkin değil.');}catch(error){const code=error.message;throw new Error(pkiErrors[code]||code);}finally{for(const name of ['ca_password','password','confirm'])if(name in data)data[name]='';clearPKISecrets();pkiBusy=false;pkiControls();}}
$('pki-init-form').addEventListener('submit',event=>{event.preventDefault();run(()=>pkiAction('/api/pki/initialize',{confirm:$('pki-confirm').value}));});
$('pki-user-form').addEventListener('submit',event=>{event.preventDefault();run(()=>pkiAction('/api/pki/enroll-user',{csr:$('pki-csr').value,username:$('pki-username').value.trim(),password:$('pki-user-password').value,expected_revision:state.revision,days:Number($('pki-days').value)}));});
$('pki-revoke-form').addEventListener('submit',event=>{event.preventDefault();if(confirm('Bu sertifika iptal edilsin mi? İptal geri alınamaz.'))run(()=>pkiAction('/api/pki/revoke',{serial:$('pki-revoke-serial').value.trim(),reason:$('pki-reason').value}));});
$('pki-crl-refresh').addEventListener('click',()=>run(()=>pkiAction('/api/pki/refresh-crl',{})));
for(const [id,name]of [['pki-download-root','root-ca.pem'],['pki-download-issuer','issuer-ca.pem'],['pki-download-crl','issuer-crl.pem']])$(id).addEventListener('click',()=>run(async()=>{const value=await api('/api/pki/public?name='+name);downloadPEM(name,value.pem);}));
$('pki-previous').addEventListener('click',()=>run(async()=>{pkiOffset=Math.max(0,pkiOffset-100);await loadCertificates();}));$('pki-next').addEventListener('click',()=>run(async()=>{pkiOffset+=100;await loadCertificates();}));

// Presentation-only controls reuse the existing authenticated APIs.
function setPKITab(tab){pkiTab=tab;closePKIDrawer();$('device-signer-password').value='';document.querySelectorAll('[data-pki-tab]').forEach(x=>{const selected=x.dataset.pkiTab===tab;x.setAttribute('aria-selected',String(selected));x.tabIndex=selected?0:-1;});for(const name of ['bulk','distribution','devices','users','authority','revocations'])$('pki-panel-'+name).hidden=name!==tab;}
function closePKIDrawer(){pkiDrawer='';$('pki-feedback').textContent='';pkiFileGeneration++;clearPKISecrets();$('pki-csr').value='';$('pki-csr-file').value='';$('pki-file-feedback').textContent='';$('pki-username').value='';$('pki-write').hidden=true;document.body.classList.remove('pki-drawer-open');}
function openPKIDrawer(action){if(!can('certificates.authority',true)||pkiBusy)return;if(action!=='initialize'&&!state?.pki_public?.initialized)return;closePKIDrawer();pkiDrawer=action;$('pki-drawer-title').textContent={user:'Yeni kullanıcı sertifikası',initialize:'Dahili CA oluştur',revoke:'Sertifika iptali',crl:'İptal listesini yenile'}[action];pkiControls();$('pki-password').focus();}
function renderCertificateRows(){const parent=$('pki-certificates');parent.replaceChildren();const query=$('pki-search').value.trim().toLocaleLowerCase('tr');const items=pkiRows.filter(cert=>[cert.serial,({user:'AD kullanıcı',computer:'AD bilgisayar'}[cert.kind]||'RADIUS sunucusu'),({valid:'Geçerli',revoked:'İptal edildi',expired:'Süresi doldu'}[cert.status]||cert.status)].join(' ').toLocaleLowerCase('tr').includes(query));for(const cert of items){const row=document.createElement('div');row.className='certificate-row';for(const value of [({user:'AD kullanıcı',computer:'AD bilgisayar'}[cert.kind]||'RADIUS sunucusu'),cert.serial,cert.not_after]){const cell=document.createElement('span');cell.textContent=value;row.append(cell);}const status=document.createElement('span');status.className='certificate-status '+({valid:'valid',revoked:'revoked',expired:'expired'}[cert.status]||'');status.textContent=({valid:'Geçerli',revoked:'İptal edildi',expired:'Süresi doldu'}[cert.status]||cert.status);row.append(status);const actions=document.createElement('div');actions.className='certificate-actions';const download=document.createElement('button');download.textContent='İndir';download.addEventListener('click',()=>run(async()=>{const value=await api('/api/pki/certificate?serial='+encodeURIComponent(cert.serial));downloadPEM('authwire-'+cert.serial+'.pem',value.pem);}));actions.append(download);if(can('certificates.authority',true)&&cert.status!=='revoked'){const revoke=document.createElement('button');revoke.textContent='İptal';revoke.className='danger';revoke.addEventListener('click',()=>{openPKIDrawer('revoke');$('pki-revoke-serial').value=cert.serial;});actions.append(revoke);}if(can('certificates.authority',true)&&cert.status==='revoked'){const archive=document.createElement('button');archive.textContent='Panelden kaldır';archive.addEventListener('click',()=>run(()=>archiveCertificate(cert)));actions.append(archive);}row.append(actions);parent.append(row);}if(!items.length){const empty=document.createElement('div');empty.className='empty-state';const symbol=document.createElement('div');symbol.className='empty-symbol';symbol.setAttribute('aria-hidden','true');symbol.textContent='◇';const title=document.createElement('h3');title.textContent=query?'Aramada sonuç bulunamadı':'Henüz sertifika yok';const note=document.createElement('p');note.textContent=query?'Arama bu sayfadaki kayıtları kapsar.':'İstemcinin CSR dosyası ve AD kimliği doğrulandıktan sonra sertifika burada listelenir.';empty.append(symbol,title,note);if(!query&&can('certificates.authority',true)){const add=document.createElement('button');add.textContent=state?.pki_public?.initialized?'Yeni sertifika':'Önce CA oluştur';add.className='primary';add.disabled=pkiBusy;add.addEventListener('click',()=>openPKIDrawer(state?.pki_public?.initialized?'user':'initialize'));empty.append(add);}parent.append(empty);}}
document.querySelectorAll('[data-open-view]').forEach(button=>button.addEventListener('click',()=>showView(button.dataset.openView)));
document.querySelectorAll('[data-pki-tab]').forEach(button=>{button.addEventListener('click',()=>setPKITab(button.dataset.pkiTab));button.addEventListener('keydown',event=>{const names=['bulk','distribution','devices','users','authority','revocations'];let index=names.indexOf(button.dataset.pkiTab);if(event.key==='ArrowRight')index=(index+1)%names.length;else if(event.key==='ArrowLeft')index=(index+names.length-1)%names.length;else if(event.key==='Home')index=0;else if(event.key==='End')index=names.length-1;else return;event.preventDefault();setPKITab(names[index]);$('pki-tab-'+names[index]).focus();});});
$('pki-new').addEventListener('click',()=>openPKIDrawer('user'));$('pki-open-init').addEventListener('click',()=>openPKIDrawer('initialize'));$('pki-open-revoke').addEventListener('click',()=>openPKIDrawer('revoke'));$('pki-open-crl').addEventListener('click',()=>openPKIDrawer('crl'));$('pki-close').addEventListener('click',()=>{closePKIDrawer();$('pki-new').focus();});$('pki-authority-link').addEventListener('click',()=>setPKITab('authority'));$('pki-search').addEventListener('input',renderCertificateRows);
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&pkiDrawer&&!pkiBusy){closePKIDrawer();$('pki-new').focus();}});
$('pki-csr-file').addEventListener('change',()=>run(async()=>{const file=$('pki-csr-file').files[0],generation=++pkiFileGeneration,auth=authGeneration;$('pki-csr').value='';$('pki-file-feedback').textContent='';if(!file)return;if(file.size>65536)throw new Error('CSR dosyası en fazla 64 KB olabilir.');const content=await file.text();if(generation!==pkiFileGeneration||auth!==authGeneration||pkiDrawer!=='user')return;if(content.includes('PRIVATE KEY')||!content.includes('-----BEGIN CERTIFICATE REQUEST-----')||!content.includes('-----END CERTIFICATE REQUEST-----')){$('pki-csr-file').value='';throw new Error('Yalnız PEM CSR dosyası seçin; özel anahtar yüklenmez.');}$('pki-csr').value=content;$('pki-file-feedback').textContent='CSR dosyası forma alındı. İmza ve içerik sertifika oluşturulurken doğrulanır.';message('CSR dosyası forma alındı.');}));
$('page-go').addEventListener('click',()=>{const query=$('page-search').value.trim().toLocaleLowerCase('tr');const match=Object.entries(viewNames).find(([id,name])=>name.toLocaleLowerCase('tr')===query&&(viewPermissions[id]||[]).some(k=>can(k)));if(match){showView(match[0]);$('page-search').value='';}else message('Menüden erişiminiz olan bir bölüm seçin.');});$('page-search').addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();$('page-go').click();}});

function renderOverview(){const d=state?.directory_public,counts=d?.counts,visible=can('directory.catalog')||can('directory.connection');$('overview-users').textContent=visible&&d?.catalog_available?String(counts?.users??0):'—';$('overview-groups').textContent=visible&&d?.catalog_available?String(counts?.groups??0):'—';$('identity-users-total').textContent=can('directory.catalog')&&d?.catalog_available?String(counts?.users??0):'—';$('identity-groups-total').textContent=can('directory.catalog')&&d?.catalog_available?String(counts?.groups??0):'—';$('identity-computers-total').textContent=can('directory.catalog')&&d?.catalog_available?String(counts?.computers??0):'—';$('overview-policies').textContent=can('policies.rules')?String(state?.policies?.length??0):'—';const statuses=[['journey-config',can('setup.directory')||can('directory.connection'),!!state?.directory_context?.configured,'Temel kayıt hazır','Hazırlanacak'],['journey-users',can('directory.catalog'),!!d?.catalog_available,'Dizin okundu','Okuma bekliyor'],['journey-policies',can('policies.rules'),!!state?.policies?.length,'Kurallar kayıtlı','Hazırlanacak']];for(const [id,allowed,ready,yes,no]of statuses){$(id).textContent=allowed?(ready?yes:no):'Yetki yok';$(id).classList.toggle('done',allowed&&ready);}const health=state?.directory_health,authority=state?.pki_public;
$('overview-directory-row').hidden=!visible;
$('overview-authority-row').hidden=!can('certificates.authority');
$('overview-computers').textContent='AD bilgisayarları: '+(can('directory.catalog')&&d?.catalog_available?String(counts?.computers??0):'—');
const dirBadge=$('overview-directory-health');dirBadge.textContent=health?.state==='error'?'Kontrol gerekli':d?.catalog_available?'Dizin okundu':'Bekliyor';dirBadge.dataset.status=health?.state==='error'?'error':d?.catalog_available?'ready':'pending';
$('overview-directory-detail').textContent=visible&&d?.catalog_available?'Son okuma: '+(d.synced_at||'Zaman bilgisi yok'):'LDAP bağlantısı ve dizin okumasını hazırlayın.';
const caBadge=$('overview-authority-health'),expires=authority?.issuer?.not_after,expiry=expires?Date.parse(expires):NaN,expired=Number.isFinite(expiry)&&expiry<=Date.now();
caBadge.textContent=authority?.initialized?(expired?'Süresi doldu':'CA oluşturuldu'):'Bekliyor';caBadge.dataset.status=authority?.initialized?(expired?'error':'ready'):'pending';
$('overview-authority-detail').textContent=can('certificates.authority')&&authority?.initialized?(Number.isFinite(expiry)?'İmzalayan CA son geçerlilik: '+new Date(expiry).toLocaleDateString('tr-TR'):'Geçerlilik bilgisi yok'):'Sertifika otoritesini hazırlayın.';
}
function setIdentityTab(tab){for(const name of ['users','groups','computers']){const selected=name===tab,button=$('identity-tab-'+name);button.setAttribute('aria-selected',String(selected));button.tabIndex=selected?0:-1;$('identity-panel-'+name).hidden=!selected;}}
document.querySelectorAll('[data-identity-tab]').forEach(button=>{button.addEventListener('click',()=>setIdentityTab(button.dataset.identityTab));button.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const names=['users','groups','computers'],index=names.indexOf(button.dataset.identityTab);const tab=event.key==='Home'?names[0]:event.key==='End'?names[names.length-1]:names[(index+(event.key==='ArrowRight'?1:names.length-1))%names.length];setIdentityTab(tab);$('identity-tab-'+tab).focus();});});
$('nav-toggle').addEventListener('click',()=>setNavigation(!document.body.classList.contains('nav-open')));$('nav-scrim').addEventListener('click',()=>{setNavigation(false);$('nav-toggle').focus();});document.addEventListener('keydown',event=>{if(event.key==='Escape'&&document.body.classList.contains('nav-open')){setNavigation(false);$('nav-toggle').focus();}if(event.key==='/'&&session&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!pkiDrawer&&!$('directory-detail').open){event.preventDefault();$('page-search').focus();}});

window.matchMedia('(max-width:760px)').addEventListener('change',()=>setNavigation(false));setNavigation(false);

